// @uat-only begin startProjectManagerSubscription
function startProjectManagerSubscription(isCurrentSession) {
  stopProjectManagerSubscription();
  return new Promise((resolve, reject) => {
    let initial = true;
    projectManagerUnsub = onSnapshot(collection(db, 'users'), snapshot => {
      if (!isCurrentSession()) return;
      const accounts = snapshot.docs.map(entry => ({ id: entry.id, ...entry.data() }));
      projectDraftDirectory = { authGeneration:authSessionGeneration, options:accounts.filter(account => normalizeDashboardRole(account.role) === 'pm').map(account => ({email:account.id,name:account.displayName || account.id})) };
      displayNameDirectory.replace(accounts);
      PM_LIST = buildProjectManagerList(accounts, getUserDisplayName);
      syncProjectManagerFilterOptions();
      if (allWeeks.length) render();
      if (initial) {
        initial = false;
        resolve(PM_LIST);
      }

